/**
 * Retries a callback up to `retries` times if it throws (or rejects).
 *
 * @param {Function} fn - The function to call. Receives the attempt number (starting at 1).
 * @param {number} retries - Maximum number of retries after the first attempt.
 * @param {Object} [options]
 * @param {number} [options.delay=0] - Base delay in ms between attempts.
 * @param {number} [options.backoff=1] - Multiplier applied to the delay after each failure.
 * @param {Function} [options.shouldRetry] - (error, attempt) => boolean; return false to stop early.
 * @param {Function} [options.onRetry] - (error, attempt) => void; called before each retry.
 * @returns {Promise<*>} Resolves with fn's result, or rejects with the last error.
 */
async function retry(fn, retries = 3, options = {}) {
  const {
    delay = 0,
    backoff = 1,
    shouldRetry = () => true,
    onRetry = () => {},
  } = options;

  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError("retries must be a non-negative integer");
  }

  let currentDelay = delay;
  let lastError;

  for (let attempt = 1; attempt <= retries + 1; attempt++) {
    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;

      const isLastAttempt = attempt > retries;
      if (isLastAttempt || !shouldRetry(error, attempt)) {
        break;
      }

      onRetry(error, attempt);

      if (currentDelay > 0) {
        await new Promise((resolve) => setTimeout(resolve, currentDelay));
      }
      currentDelay *= backoff;
    }
  }

  throw lastError;
}
```

