const result = await retry(() => {
  count++;
  if (count < 3) throw new Error(`Fail #${count}`);
  return "Success!";
}, 5);
console.log(result); // "Success!" (after 3 attempts)

// 2. Async callback with exponential backoff
const data = await retry(
  async () => {
    const res = await fetch("https://api.example.com/data");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  },
  4,
  {
    delay: 500,   // 500ms, 1000ms, 2000ms, 4000ms
    backoff: 2,
    onRetry: (err, attempt) => console.warn(`Attempt ${attempt} failed: ${err.message}`),
  }
);

// 3. Only retry certain errors
await retry(doSomething, 3, {
  shouldRetry: (err) => err.code !== "INVALID_INPUT", // don't retry bad input
});

// 4. Handling final failure
