// 1. Basic usage with a flaky function
let count = 0;
const flaky = () => {
  count++;
  if (count < 3) throw new Error(`Failed on attempt ${count}`);
  return 'Success!';
};

retry(flaky, 5).then(console.log); // "Success!" (after 3 attempts)

// 2. Async function with exponential backoff
const data = await retry(
  async () => {
    const res = await fetch('https://api.example.com/data');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  },
  3,
  {
    delay: 500,  // 500ms, then 1000ms, then 2000ms
    backoff: 2,
    onRetry: (err, attempt) => console.warn(`Attempt ${attempt} failed: ${err.message}`),
  }
);

// 3. Only retry on certain errors
await retry(doSomething, 3, {
  shouldRetry: (err) => err.code !== 'INVALID_INPUT', // don't retry validation errors
});

// 4. Synchronous version
const result = retrySync(() => JSON.parse(maybeBadInput()), 2);
```

## Key Design Decisions

- **`retries` means retries, not total attempts**: `retry(fn, 3)` runs up to 4 times (1 initial + 3 retries). If you want N total attempts, change the loop condition to `attempt <= retries`.
- **Works with sync and async**: `await` on a non-promise value just returns it, so sync callbacks work fine, though the result is always a Promise.
- **Throws the last error**: preserves the original error type and stack trace so callers can handle it normally.
- **No delay after the final failure**: avoids needlessly waiting before throwing.
- **`shouldRetry` hook**: lets you bail out early on non-transient errors (e.g. 4xx HTTP responses).

Here's a flexible retry function that handles both synchronous and asynchronous callbacks:

```javascript
/**
 * Retries a callback up to `retries` times if it throws (or rejects).
 *
 * @param {Function} fn - The callback to execute. Receives the current attempt number (1-based).
 * @param {number} retries - Maximum number of retries after the first attempt.
 * @param {Object} [options]
 * @param {number} [options.delay=0] - Base delay in ms between attempts.
 * @param {number} [options.backoff=1] - Multiplier applied to the delay after each failure.
 * @param {Function} [options.shouldRetry] - (error, attempt) => boolean; return false to stop early.
 * @param {Function} [options.onRetry] - (error, attempt) => void; called before each retry.
 * @returns {Promise<*>} Resolves with the callback's result, or rejects with the last error.
 */
async function retry(fn, retries = 3, options = {}) {
  const {
    delay = 0,
    backoff = 1,
    shouldRetry = () => true,
    onRetry = () => {},
  } = options;

  if (typeof fn !== 'function') {
    throw new TypeError('retry: first argument must be a function');
  }
  if (!Number.isInteger(retries) || retries < 0) {
    throw new RangeError('retry: retries must be a non-negative integer');
  }

  let currentDelay = delay;
  let lastError;

  for (let attempt = 1; attempt <= retries + 1; attempt++) {
    try {
      // `await` handles both sync return values and promises
      return await fn(attempt);
    } catch (error) {
      lastError = error;

      const isLastAttempt = attempt > retries;
      if (isLastAttempt || !shouldRetry(error, attempt)) {
        break;
      }

      onRetry(error, attempt);

      if (currentDelay > 0) {
        await new Promise((resolve) => setTimeout(resolve, currentDelay));
        currentDelay *= backoff;
      }
    }
  }

  throw lastError;
}
```

### Usage examples

**Basic usage:**
```javascript
let count = 0;

const result = await retry(() => {
  count++;
  if (count < 3) throw new Error(`Failed attempt ${count}`);
  return 'Success!';
}, 5);

console.log(result); // "Success!" (after 3 attempts)
```

**With async functions and exponential backoff:**
```javascript
