# Retry Function in JavaScript

```javascript
/**
 * Runs `fn`, retrying up to `N` times if it throws.
 * @param {Function} fn - The async/sync callback to run.
 * @param {number} retries - Max number of retries (default 3).
 * @param {number} delay - Delay between attempts in ms (default 0).
 * @returns {Promise<*>} Resolves with fn's result, or rejects with the last error.
 */
async function retry(fn, retries = 3, delay = 0) {
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;
      if (attempt < retries && delay > 0) {
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError;
}
```

## Usage

```javascript
