 * Groups an array of objects by a given key.
 *
 * @param {Array<Object>} arr - The array of objects to group.
 * @param {string|Function} key - The property name, or a function that returns the grouping key.
 * @returns {Object} An object where each key maps to an array of matching items.
 */
function groupBy(arr, key) {
  if (!Array.isArray(arr)) {
    throw new TypeError('Expected an array as the first argument');
  }

  const getKey = typeof key === 'function' ? key : (item) => item[key];

  return arr.reduce((acc, item) => {
    const groupKey = getKey(item);
    (acc[groupKey] ||= []).push(item);
    return acc;
  }, {});
}
