  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await callback(attempt);
    } catch (err) {
      lastError = err;
      if (attempt < retries) {
        const wait = baseDelay * 2 ** attempt + Math.random() * 100; // jitter
        await new Promise((r) => setTimeout(r, wait));
      }
    }
  }
  throw lastError;
