  const { delay = 0, onRetry, shouldRetry = () => true } = options;
  let lastError;

  for (let attempt = 1; attempt <= retries + 1; attempt++) {
    try {
      return await callback();
    } catch (err) {
      lastError = err;

      const isLastAttempt = attempt === retries + 1;
      if (isLastAttempt || !shouldRetry(err, attempt)) break;

      if (onRetry) onRetry(err, attempt);
      if (delay > 0) await new Promise((r) => setTimeout(r, delay));
    }
  }

  throw lastError;
}
```

## Usage with Backoff

```javascript
const result = await retryAsync(
  () => fetch('https://api.example.com/data').then(r => r.json()),
  3,
  {
    delay: 500,
    onRetry: (err, attempt) => console.warn(`Retry ${attempt}: ${err.message}`),
    shouldRetry: (err) => !err.message.includes('404'), // don't retry client errors
  }
);
```

### Design notes

- **`retries + 1` total attempts** — with `retries = 3`, the callback runs at most 4 times (1 initial + 3 retries). If you'd rather have `N` total attempts, loop `attempt < N`.
- **`shouldRetry`** lets you bail early on non-retryable errors (e.g., 4xx HTTP responses).
- **The last error is rethrown**, preserving the original stack trace.

