    try {
      return callback();
    } catch (err) {
      lastError = err;
      // If this was the last attempt, don't wait — just throw.
      if (attempt === maxRetries) break;
      if (delayMs > 0) sleepSync(delayMs);
    }
  }

  throw lastError;
}

// Simple synchronous sleep (blocks the thread).
