 * @param {(err: Error, attempt: number) => void} [onRetry] - Optional hook.
 * @returns {*} The return value of `fn` on success.
 * @throws The last error if all attempts fail.
 */
function retry(fn, retries = 3, onRetry) {
  if (typeof fn !== 'function') throw new TypeError('fn must be a function');
  if (!Number.isInteger(retries) || retries < 0) {
    throw new TypeError('retries must be a non-negative integer');
  }

  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return fn(attempt);
    } catch (err) {
      lastError = err;
      if (attempt < retries && onRetry) onRetry(err, attempt + 1);
