  let lastError;
  let wait = delayMs;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;
      if (attempt < retries && wait > 0) {
        await new Promise(r => setTimeout(r, wait));
        wait *= backoff; // exponential backoff if backoff > 1
      }
    }
  }
  throw lastError;
}
```

### Usage

```javascript
