## Basic Implementation

```javascript
function groupBy(array, key) {
  return array.reduce((acc, item) => {
    const groupKey = item[key];
    (acc[groupKey] ||= []).push(item);
    return acc;
  }, {});
}
```

**Example:**

```javascript
const users = [
  { name: 'Alice', role: 'admin' },
  { name: 'Bob',   role: 'user' },
  { name: 'Carol', role: 'admin' },
  { name: 'Dave',  role: 'user' },
];

console.log(groupBy(users, 'role'));
// {
//   admin: [{ name: 'Alice', role: 'admin' }, { name: 'Carol', role: 'admin' }],
//   user:  [{ name: 'Bob', role: 'user' },   { name: 'Dave', role: 'user' }]
// }
```

## More Flexible Version

Supports nested keys (`'a.b.c'`), a custom callback, and a `Map` for non-string keys.

```javascript
function groupBy(array, keyOrFn) {
  const getKey = typeof keyOrFn === 'function'
    ? keyOrFn
    : (item) => keyOrFn.split('.').reduce((obj, k) => (obj == null ? obj : obj[k]), item);

  const result = new Map();

  for (const item of array) {
    const groupKey = getKey(item);
    if (!result.has(groupKey)) {
      result.set(groupKey, []);
    }
    result.get(groupKey).push(item);
  }

  return result;
}
```

**Examples:**

```javascript
const data = [
  { id: 1, meta: { dept: 'sales' } },
  { id: 2, meta: { dept: 'eng' } },
  { id: 3, meta: { dept: 'sales' } },
];

// Nested key
groupBy(data, 'meta.dept');
// Map { 'sales' => [...], 'eng' => [...] }

// Custom callback
groupBy(data, (item) => item.id % 2 === 0 ? 'even' : 'odd');
// Map { 'odd' => [...], 'even' => [...] }
```

## Notes

- **Key order:** `Map` preserves insertion order; plain objects do not guarantee numeric-like keys stay in order.
