snakeToCamel('hello_world');        // 'helloWorld'
snakeToCamel('user_id');            // 'userId'
snakeToCamel('my_variable_name');   // 'myVariableName'
snakeToCamel('already_camelCase');  // 'alreadyCamelcase'
snakeToCamel('');                   // ''
