## More robust version (with options)

```js
/**
 * Convert snake_case to camelCase (or PascalCase).
 *
 * @param {string} input
 * @param {object} [options]
 * @param {boolean} [options.pascal=false]                 Capitalize the first letter too.
 * @param {boolean} [options.lowercase=false]              Lowercase the whole string first.
 * @param {boolean} [options.preserveLeadingUnderscores=false] Keep leading "_" instead of eating it.
 * @returns {string}
 */
function snakeToCamel(input, options = {}) {
  const {
    pascal = false,
    lowercase = false,
    preserveLeadingUnderscores = false,
  } = options;

  if (typeof input !== 'string') {
    throw new TypeError('snakeToCamel expects a string');
  }

  // Pull off leading underscores so they don't get merged into the first word.
  const leading = input.match(/^_*/)[0];
  let body = input.slice(leading.length);

  if (lowercase) body = body.toLowerCase();

  const camel = body.replace(/_+(\w)/g, (_, char) => char.toUpperCase());

  const result = pascal
    ? camel.charAt(0).toUpperCase() + camel.slice(1)
    : camel;

  return preserveLeadingUnderscores ? leading + result : result;
}
```

