## Simple synchronous version

```js
function retry(fn, retries = 3) {
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return fn(attempt); // attempt is 0-based
    } catch (err) {
      lastError = err;
      if (attempt === retries) break;
    }
  }

  throw lastError;
}
```

**Usage:**

```js
const result = retry(() => JSON.parse(badJson), 3);
```

> Note: `retries = 3` means up to **4** total calls (1 initial + 3 retries). Set `retries = 0` for a single attempt.

---

## Async version with delay (more practical)

```js
async function retryAsync(fn, { retries = 3, delay = 1000, backoff = 2 } = {}) {
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;
      if (attempt === retries) break;

      await new Promise((resolve) => setTimeout(resolve, delay));
      delay *= backoff; // exponential backoff
    }
  }

  throw lastError;
}
```

**Usage:**

```js
const data = await retryAsync(
  async () => {
    const res = await fetch('/api/data');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  },
  { retries: 5, delay: 500 }
);
```

---

## Key details

- **The callback receives the attempt number**, so you can vary behavior (e.g., different endpoints per attempt).
- **The last error is rethrown** after all attempts fail, so callers still see a meaningful failure.
- **Don't retry non-retryable errors.** A common pattern is to only retry on specific error types:

```js
async function retryAsync(fn, { retries = 3, delay = 1000, shouldRetry = () => true } = {}) {
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;
      if (attempt === retries || !shouldRetry(err)) break;
      await new Promise((r) => setTimeout(r, delay));
    }
  }

  throw lastError;
}

// Only retry on 5xx / network errors
await retryAsync(task, {
  shouldRetry: (err) => err.status >= 500 || err.code === 'ECONNRESET',
});
```

- **Avoid infinite retries** — always cap the count, and consider a total timeout budget for long-running operations.

