## Implementation

```js
/**
 * Calls `fn` until it succeeds, retrying on thrown errors / rejected promises.
 *
 * @param {Function} fn            Callback to run. Receives the 0-based attempt index.
 * @param {Object}   [options]
 * @param {number}   [options.attempts=3]    Total number of tries (1 = no retries).
 * @param {number}   [options.delay=0]       Base delay in ms before the first retry.
 * @param {number}   [options.backoff=1]     Multiplier applied to the delay each retry.
 * @param {number}   [options.maxDelay=Infinity]  Upper bound for a single delay.
 * @param {Function} [options.shouldRetry]   (err, attemptIndex) => boolean. Return false to fail fast.
 * @param {Function} [options.onRetry]       (err, nextAttempt, waitMs) => void. Logging hook.
 * @param {AbortSignal} [options.signal]     Cancels pending retries.
 * @returns {Promise<any>} Resolves with fn's result, or rejects with the last error.
 */
async function retry(fn, options = {}) {
  const {
    attempts = 3,
    delay = 0,
    backoff = 1,
    maxDelay = Infinity,
    shouldRetry = () => true,
    onRetry = () => {},
    signal,
  } = options;

  if (typeof fn !== 'function') throw new TypeError('fn must be a function');
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be a positive integer');
  }

  let lastError;

  for (let i = 0; i < attempts; i++) {
    throwIfAborted(signal);

    try {
      return await fn(i); // `await` covers both sync throws and rejected promises
    } catch (err) {
      lastError = err;

      const isLastAttempt = i === attempts - 1;
      if (isLastAttempt || !shouldRetry(err, i)) throw err;

      const wait = Math.min(delay * backoff ** i, maxDelay);
      onRetry(err, i + 1, wait);

      if (wait > 0) await sleep(wait, signal);
    }
  }

  throw lastError; // unreachable, but keeps the contract explicit
}

/* ---------- helpers ---------- */

function throwIfAborted(signal) {
  if (signal?.aborted) {
    throw signal.reason ?? new Error('Aborted');
  }
}

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason ?? new Error('Aborted'));

    const onAbort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new Error('Aborted'));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
```

## Usage

```js
// Basic: 3 total attempts
await retry(() => fetchData(), { attempts: 3 });

// Exponential backoff: 100ms, 200ms, 400ms...
await retry(() => fetchData(), {
  attempts: 5,
  delay: 100,
  backoff: 2,
  maxDelay: 2000,
  onRetry: (err, attempt, wait) =>
    console.warn(`Attempt ${attempt} failed (${err.message}); retrying in ${wait}ms`),
});

// Don't retry 4xx client errors — only 5xx and network failures
await retry(() => api.call(), {
  attempts: 4,
  shouldRetry: (err) => err.status >= 500 || err.code === 'ECONNRESET',
});

// Cancellable
const controller = new AbortController();
setTimeout(() => controller.abort(), 1000);
await retry(() => slowCall(), { attempts: 10, delay: 500, signal: controller.signal });
```

## Notes

- **`attempts` is the total number of calls**, not the number of *extra* retries. `attempts: 3` means one initial call plus two retries. If you want "N retries after the first try," pass `attempts: N + 1`.
- **The last error is rethrown** unchanged, so callers can inspect `err.status`, `err.code`, etc. The original stack is preserved.
- **`await fn(i)`** means the same function handles synchronous callbacks and async ones (returning a promise) uniformly.
- **Fail-fast via `shouldRetry`** is the idiomatic way to avoid hammering a server with requests that will never succeed (e.g. HTTP 400).

### Synchronous variant

If you don't need promises, a plain loop is simpler:

```js
function retrySync(fn, { attempts = 3, delay = 0, backoff = 1 } = {}) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return fn(i);
    } catch (err) {
      lastError = err;
      if (i === attempts - 1) throw err;
      const wait = delay * backoff ** i;
      if (wait > 0) {
        const end = Date.now() + wait;
        while (Date.now() < end) { /* busy-wait */ }
      }
    }
  }
  throw lastError;
}
```

For the sync case, prefer the async version anyway — blocking the event loop during a backoff is rarely what you want in Node.js.

## Implementation

```js
/**
 * Runs `fn`, retrying it if it throws (or returns a rejected promise).
 *
 * @param {Function} fn            Callback to run. Receives the 0-based attempt index.
 * @param {Object}   [options]
 * @param {number}   [options.attempts=3]     Total number of tries (not extra retries).
 * @param {number}   [options.delay=0]        Base delay in ms between tries.
 * @param {number}   [options.backoff=1]      Multiplier applied to the delay each try.
 * @param {number}   [options.maxDelay=Infinity]  Upper bound for a single delay.
 * @param {Function} [options.shouldRetry]    (err, attemptIndex) => boolean.
 * @param {Function} [options.onRetry]        (err, nextAttempt, waitMs) => void.
 * @param {AbortSignal} [options.signal]      Cancel the whole operation.
 * @returns {Promise<any>} Resolves with fn's value, or rejects with the last error.
 */
async function retry(fn, options = {}) {
  const {
    attempts = 3,
    delay = 0,
    backoff = 1,
    maxDelay = Infinity,
    shouldRetry = () => true,
    onRetry = () => {},
    signal,
  } = options;

  if (typeof fn !== 'function') throw new TypeError('retry: fn must be a function');
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('retry: attempts must be a positive integer');
  }

  let lastError;

  for (let i = 0; i < attempts; i++) {
    if (signal?.aborted) throw abortError(signal);

    try {
      return await fn(i); // `await` covers both sync throws and rejected promises
    } catch (err) {
      lastError = err;

      const isLastAttempt = i === attempts - 1;
      if (isLastAttempt || !shouldRetry(err, i)) throw err;

      const wait = Math.min(delay * backoff ** i, maxDelay);
      onRetry(err, i + 1, wait);
      if (wait > 0) await sleep(wait, signal);
    }
  }

  throw lastError; // unreachable, but keeps static analyzers happy
}

function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(abortError(signal));

    const onAbort = () => {
      clearTimeout(timer);
      reject(abortError(signal));
    };

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

function abortError(signal) {
  return signal.reason ?? new DOMException('The operation was aborted.', 'AbortError');
}
```

