## Implementation

```js
/**
 * Sleep for `ms` milliseconds, optionally abortable via an AbortSignal.
 */
function sleep(ms, signal) {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(signal.reason ?? new Error('Aborted'));

    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason ?? new Error('Aborted'));
    }

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * Run `fn`, retrying it if it throws/rejects.
 *
 * @param {Function} fn              Callback to run. Receives the 0-based attempt index.
 * @param {Object}   [options]
 * @param {number}   [options.attempts=3]     Total number of tries (not extra retries).
 * @param {number}   [options.delay=0]        Base delay in ms between tries.
 * @param {number}   [options.backoff=1]      Multiplier applied to the delay each try.
 * @param {number}   [options.maxDelay=Infinity]  Upper bound for a single delay.
 * @param {Function} [options.shouldRetry]    (error, attemptIndex) => boolean.
 * @param {Function} [options.onRetry]        (error, nextAttemptIndex, waitMs) => void.
 * @param {AbortSignal} [options.signal]      Cancels pending waits.
 * @returns {Promise<any>} Resolves with `fn`'s result, or rejects with the last error.
 */
async function retry(fn, options = {}) {
  const {
    attempts = 3,
    delay = 0,
    backoff = 1,
    maxDelay = Infinity,
    shouldRetry = () => true,
    onRetry = () => {},
    signal,
  } = options;

  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('`attempts` must be an integer >= 1');
  }

  let lastError;

  for (let i = 0; i < attempts; i++) {
    try {
      return await fn(i);
    } catch (error) {
      lastError = error;

      const isLastAttempt = i === attempts - 1;
      if (isLastAttempt || !shouldRetry(error, i)) throw error;

      const wait = Math.min(delay * backoff ** i, maxDelay);
      onRetry(error, i + 1, wait);

      if (wait > 0) await sleep(wait, signal);
    }
  }

  // Unreachable in practice, but keeps the contract explicit.
  throw lastError;
}

module.exports = { retry, sleep };
```

