 * @param {number}   [options.delay=0]        Base delay in ms between attempts.
 * @param {number}   [options.factor=1]        Backoff multiplier (2 => delay, 2*delay, 4*delay...).
 * @param {number}   [options.maxDelay=Infinity] Upper bound for a single delay.
 * @param {Function} [options.shouldRetry]     (err, attempt) => boolean. Return false to fail fast.
 * @param {Function} [options.onRetry]         (err, attempt, waitMs) => void. Side-effect hook.
 * @returns {Promise<*>} Resolves with the callback's value, rejects with the last error.
 */
async function retry(fn, options = {}) {
