 * @param {number}   [options.backoff=1]    Multiplier applied to the delay each retry.
 * @param {boolean}  [options.jitter=false] Randomize the delay (avoids thundering herds).
 * @param {Function} [options.onRetry]      Called as onRetry(error, attemptNumber) before each retry.
 * @param {AbortSignal} [options.signal]    Abort to cancel pending retries.
 * @returns {Promise<any>} The callback's resolved value.
 */
async function retry(fn, options = {}) {
  const {
    attempts = 3,
    delay = 0,
    backoff = 1,
    jitter = false,
    onRetry = null,
    signal = null,
  } = options;

  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new TypeError('`attempts` must be an integer >= 1');
  }

  let lastError;

  for (let attempt = 1; attempt <= attempts; attempt++) {
    if (signal?.aborted) {
      throw signal.reason ?? new DOMException('Aborted', 'AbortError');
    }

    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;

      if (attempt === attempts) break; // out of tries — give up
      if (onRetry) onRetry(error, attempt);

      const wait = delay * backoff ** (attempt - 1);
      await sleep(jitter ? Math.random() * wait : wait, signal);
    }
  }

  throw lastError;
}

/** Promise-based sleep that resolves early if the signal is aborted. */
function sleep(ms, signal) {
  if (ms <= 0) return Promise.resolve();
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);

    function onAbort() {
      clearTimeout(timer);
      reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
    }

    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

