const result = retry(() => JSON.parse(badJson), { attempts: 3 });

// Async callback
await retry(() => fetch('/api/data'), {
  attempts: 5,
  delay: 100,
  factor: 2,                       // 100ms, 200ms, 400ms, 800ms
  onRetry: (err, attempt) => console.warn(`Attempt ${attempt} failed:`, err.message),
});

// The callback knows which attempt it is on
