## Implementation

```js
/**
 * Retries `fn` until it succeeds or the attempt budget is exhausted.
 *
 * @param {Function} fn        Callback to run. Receives the attempt number (0-based).
 * @param {Object}   [options]
 * @param {number}   [options.retries=3]     Number of *retries* after the first try
 *                                           (total attempts = retries + 1).
 * @param {number}   [options.delay=0]       Initial delay in ms between attempts.
 * @param {number}   [options.factor=2]      Backoff multiplier applied to the delay.
 * @param {Function} [options.onRetry]       Called with (error, nextAttemptNumber).
 * @returns {Promise<*>} Resolves with the callback's value, or rejects with the last error.
 */
async function retry(fn, { retries = 3, delay = 0, factor = 2, onRetry } = {}) {
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;

      if (attempt === retries) break;              // no attempts left
      if (onRetry) onRetry(err, attempt + 1);

      if (delay > 0) {
        await new Promise((resolve) => setTimeout(resolve, delay));
        delay *= factor;                           // exponential backoff
      }
    }
  }

  throw lastError;
}
```

`await fn(...)` means it works with both synchronous callbacks and promise-returning ones.

## Usage

```js
// Total of 4 attempts (1 initial + 3 retries), 100 ms base delay, doubling each time.
const result = await retry(
  async () => {
    const res = await fetch('https://api.example.com/data');
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res.json();
  },
  {
    retries: 3,
    delay: 100,
    factor: 2,
    onRetry: (err, attempt) => console.warn(`Attempt ${attempt} failed: ${err.message}`),
  }
);
```

Sync callback example:

```js
