## Basic synchronous version

```js
/**
 * Retries `fn` up to `attempts` times if it throws.
 * @param {Function} fn        - The callback to run
 * @param {number}   attempts - Maximum number of attempts (must be >= 1)
 * @param {Function} [onError] - Optional handler called with (error, attempt)
 * @returns {*} The successful return value of `fn`
 * @throws  {Error} The last error, if every attempt failed
 */
function retry(fn, attempts = 3, onError) {
  if (typeof fn !== 'function') throw new TypeError('fn must be a function');
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError('attempts must be a positive integer');
  }

  let lastError;

  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return fn(attempt); // pass the attempt number for convenience
    } catch (err) {
      lastError = err;
      if (onError) onError(err, attempt);
      if (attempt === attempts) break; // no more retries
    }
  }

  throw lastError;
}
```

**Usage:**

```js
const result = retry(() => JSON.parse(badJson), 3, (err, attempt) => {
  console.warn(`Attempt ${attempt} failed: ${err.message}`);
});
```

