## Async version with delay and exponential backoff

```js
/**
 * Retries an async callback with a delay between attempts.
 * @param {Function} fn             - async callback
 * @param {number}   attempts       - max attempts
 * @param {object}   [options]
 * @param {number}   [options.delay=100]        - base delay in ms
 * @param {number}   [options.backoff=2]        - multiplier per attempt
 * @param {number}   [options.maxDelay=5000]    - cap on delay
 * @param {Function} [options.onError]          - (error, attempt) => void
 * @param {Function} [options.shouldRetry]       - (error) => boolean
 */
async function retryAsync(fn, attempts = 3, options = {}) {
  const {
    delay = 100,
    backoff = 2,
    maxDelay = 5000,
    onError,
    shouldRetry = () => true,
  } = options;

  let lastError;

  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;

      if (onError) onError(err, attempt);

      // Don't retry on the last attempt, or if the error is not retryable.
      if (attempt === attempts || !shouldRetry(err)) break;

      const wait = Math.min(delay * backoff ** (attempt - 1), maxDelay);
      await new Promise((resolve) => setTimeout(resolve, wait));
    }
  }

  throw lastError;
}
```

**Usage:**

```js
async function fetchWithRetry(url) {
  return retryAsync(
    async () => {
      const res = await fetch(url);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    },
    5,
    {
      delay: 200,
      backoff: 2,
      shouldRetry: (err) => !err.message.startsWith('HTTP 4'), // don't retry client errors
      onError: (err, attempt) => console.warn(`Attempt ${attempt}: ${err.message}`),
    }
  );
}
```

---

### Notes
- The callback receives the current attempt number as its argument, which is handy for logging or for a "fail on the Nth try" test.
- `shouldRetry` lets you skip retrying on non‑transient errors (e.g. `400 Bad Request`).
- If you want the function to *return* the error instead of throwing, wrap the final `throw` in a `try/catch` and return `{ ok: false, error }`.

## Implementation

```js
/**
 * Calls `fn`, retrying it if it throws (or rejects).
 *
 * @param {Function} fn              Callback to run. Receives the attempt number (0-based).
 * @param {Object}   [options]
 * @param {number}   [options.retries=3]   Number of *retries* after the first attempt.
 * @param {number}   [options.delay=0]     Base delay in ms between attempts.
 * @param {number}   [options.factor=1]    Exponential backoff multiplier.
 * @param {Function} [options.shouldRetry]  (error, attempt) => boolean. Return false to fail fast.
 * @returns {Promise<*>} Resolves with the callback's result, or rejects with the last error.
 */
async function retry(fn, { retries = 3, delay = 0, factor = 1, shouldRetry } = {}) {
  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;

      const canRetry = attempt < retries
        && (shouldRetry ? shouldRetry(err, attempt) : true);

      if (!canRetry) break;

      if (delay > 0) {
        const wait = delay * Math.pow(factor, attempt);
        await new Promise(resolve => setTimeout(resolve, wait));
      }
    }
  }

  throw lastError;
}
```

## Usage

```js
// Basic: up to 3 retries (4 total attempts)
const result = await retry(async () => {
  const res = await fetch('/api/data');
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}, { retries: 3, delay: 100 });

// Exponential backoff: waits 100ms, 200ms, 400ms
await retry(flakyTask, { retries: 3, delay: 100, factor: 2 });

// Only retry on specific errors
await retry(task, {
  retries: 5,
  shouldRetry: (err) => err.code === 'ETIMEDOUT'
});

// Sync callbacks work too
const value = retry(() => JSON.parse(str), { retries: 2 });
```

## Notes

- **Sync and async callbacks** are both supported — `await fn()` handles thrown errors and rejected promises identically.
- **Attempt numbering** starts at `0`, so `fn` can use it to vary behavior (e.g., pass a different argument each time).
- **Failure semantics**: if every attempt fails, the promise rejects with the *last* error. If you need all errors, collect them yourself inside the callback or use `shouldRetry` to capture state.
- **Alternative counting**: if you prefer "N total attempts" over "N retries", change the loop bound to `attempt < retries` and drop the `attempt < retries` check in the `catch` block.

## Basic synchronous version

```js
/**
 * Retries `fn` up to `attempts` times (total tries) if it throws.
 *
 * @param {Function} fn        The callback to run.
 * @param {number}   attempts  Total number of tries (must be >= 1).
 * @param {Function} [onRetry] Optional hook called with (error, attemptNumber).
 * @returns {*} The value returned by the successful call.
 * @throws  The error from the last attempt if all attempts fail.
 */
function retry(fn, attempts = 3, onRetry) {
  if (attempts < 1) throw new RangeError('attempts must be >= 1');

  let lastError;
  for (let i = 1; i <= attempts; i++) {
    try {
      return fn(i);           // pass the attempt number for convenience
    } catch (err) {
      lastError = err;
      if (i < attempts && typeof onRetry === 'function') {
        onRetry(err, i);
      }
    }
  }
  throw lastError;
}
```

**Usage**

```js
